function setConsoleTheme(choice){if(choice==='system')document.documentElement.removeAttribute('data-theme');else document.documentElement.setAttribute('data-theme',choice);document.querySelectorAll('[data-theme-choice]').forEach(b=>{const active=b.dataset.themeChoice===choice;b.setAttribute('aria-checked',String(active));b.tabIndex=active?0:-1});try{localStorage.setItem('dh-theme',choice)}catch{}document.dispatchEvent(new CustomEvent('dh-theme-change'))}
let preferredTheme='system';try{preferredTheme=localStorage.getItem('dh-theme')||'system'}catch{}if(!['light','dark','system'].includes(preferredTheme))preferredTheme='system';setConsoleTheme(preferredTheme);
document.querySelectorAll('[data-theme-choice]').forEach(b=>{b.onclick=()=>setConsoleTheme(b.dataset.themeChoice);b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const buttons=[...document.querySelectorAll('[data-theme-choice]')];let i=buttons.indexOf(b);i=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;buttons[i].click();buttons[i].focus()}});
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const buttons=[...document.querySelectorAll('[data-tab]')];let i=buttons.indexOf(b);i=e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(e.key==='ArrowRight'?1:buttons.length-1))%buttons.length;buttons[i].click();buttons[i].focus()}));

window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(!document.documentElement.hasAttribute('data-theme'))document.dispatchEvent(new CustomEvent('dh-theme-change'))});
